import JSON
using Random
using Polynomials

"""
	gen( filepath )

Generate fixture data for `polevl` using Julia's polynomial evaluation.
"""
function gen( filepath )
	# Reproducibility:
	Random.seed!( 123456 )

	# Evaluation points:
	xs = [ -3.0, -1.5, -0.5, 0.0, 0.5, 1.0, 2.0, 3.0 ]

	results = Float64[]
	inputs_x = Float64[]
	inputs_coef = Vector{Vector{Float64}}()
	inputs_N = Int[]

	for k in 1:5
		N = rand( 0:20 )
		coef = randn( N+1 )
		p = Polynomial( coef )

		for x in xs
			y = p( x )

			push!( results, y )
			push!( inputs_x, x )
			push!( inputs_coef, coef )
			push!( inputs_N, N )
		end
	end

	data = Dict(
		"x" => inputs_x,
		"coef" => inputs_coef,
		"N" => inputs_N,
		"expected" => results
	)

	open( filepath, "w" ) do io
		write( io, JSON.json( data ) )
		write( io, "\n" )
	end
end

dir = dirname( @__FILE__ )
gen( joinpath( dir, "data.json" ) )
